        void get_join_table()
        {
            if (join_ptr == nullptr)
            {
                return;
            }

            sqlstring.append(" LEFT JOIN ");

            if (join_ptr->limitsql.empty())
            {
                sqlstring.append(join_ptr->join_table);
                sqlstring.append(" ON ");
                sqlstring.append(join_ptr->wheresql);
            }
            else
            {
                sqlstring.append(" ( SELECT ");
                if (join_ptr->selectsql.empty())
                {
                    sqlstring.append(" *,");
                }
                else
                {

                    sqlstring.append(trip_as_field(join_ptr->selectsql));

                    sqlstring.append(", ROW_NUMBER() OVER(PARTITION BY ");
                    sqlstring.append(join_ptr->parbysql);
                    sqlstring.append(" ");
                    sqlstring.append(join_ptr->ordersql);
                    sqlstring.append(") AS rn FROM ");
                    sqlstring.append(join_ptr->join_table);

                    if (join_ptr->subsql.size() > 0)
                    {
                        sqlstring.append(" WHERE ");
                        sqlstring.append(join_ptr->subsql);
                    }
                }
                sqlstring.append(" ) ");
                sqlstring.append(join_ptr->join_table);
                sqlstring.append(" ON ");
                sqlstring.append(join_ptr->wheresql);
                sqlstring.append(" AND ");
                sqlstring.append(join_ptr->join_table);
                sqlstring.append(".rn <= ");
                sqlstring.append(join_ptr->limitsql);
            }
        }
        std::string trip_as_field(std::string_view fields)
        {
            std::string str_tm_;
            unsigned int i = 0;
            for (; i < fields.size(); i++)
            {
                if (fields[i] == ' ')
                {
                    continue;
                }
                break;
            }

            for (; i < fields.size(); i++)
            {
                if (fields[i] == ' ')
                {
                    bool isneed = false;
                    for (; i < fields.size(); i++)
                    {
                        if (fields[i] == ' ')
                        {
                            continue;
                        }
                        isneed = true;
                        break;
                    }

                    if ((i + 3) < fields.size())
                    {
                        if (fields[i] == 'A' || fields[i] == 'a')
                        {
                            if (fields[i + 1] == 'S' || fields[i + 1] == 's')
                            {
                                if (fields[i + 2] == ' ')
                                {
                                    isneed = false;
                                    i      = i + 3;
                                    for (; i < fields.size(); i++)
                                    {
                                        if (fields[i] == ' ')
                                        {
                                            continue;
                                        }
                                        break;
                                    }
                                    //skip as name
                                    for (; i < fields.size(); i++)
                                    {
                                        if (fields[i] == ' ')
                                        {
                                            for (; i < fields.size(); i++)
                                            {
                                                if (fields[i] == ' ')
                                                {
                                                    continue;
                                                }
                                                break;
                                            }
                                            isneed = true;
                                            break;
                                        }
                                        else if (fields[i] == ',')
                                        {
                                            isneed = true;
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                    }
                    if (isneed)
                    {
                        i--;
                    }
                    continue;
                }
                str_tm_.push_back(fields[i]);
            }

            return str_tm_;
        }
